def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    hcuts = [r for r, row in enumerate(grid)
             if len(set(row)) == 1 and row[0] != bg]
    wcuts = [c for c in range(w)
             if len({grid[r][c] for r in range(h)}) == 1
             and grid[0][c] != bg]

    row_ranges = []
    start = 0
    for r in hcuts:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in wcuts:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    if not hcuts and not wcuts:
        return [row[:] for row in grid]

    panels = []
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            count = sum(grid[r][c] != bg
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            panels.append((count, r0, r1, c0, c1))

    source = max(panels, key=lambda p: p[0])
    if source[0] == 0:
        return [row[:] for row in grid]

    _, r0, r1, c0, c1 = source
    pattern = [(r - r0, c - c0, grid[r][c])
               for r in range(r0, r1)
               for c in range(c0, c1)
               if grid[r][c] != bg]

    out = [row[:] for row in grid]
    for count, pr0, pr1, pc0, pc1 in panels:
        if (pr0, pr1, pc0, pc1) == (r0, r1, c0, c1) or count != 0:
            continue
        for dr, dc, color in pattern:
            if pr0 + dr < pr1 and pc0 + dc < pc1:
                out[pr0 + dr][pc0 + dc] = color
    return out
